-- 25. Fannie Mae (slug=fannie-mae, wiki='Fannie Mae')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_fannie-mae_overview', 'org_fannie-mae', 'overview', 'Overview',
   'The Federal National Mortgage Association (FNMA), commonly known as Fannie Mae, is a United States government-sponsored enterprise (GSE) that has been a publicly traded company since 1968. Founded in 1938 during the Great Depression as part of the New Deal, the corporation was established to expand the secondary mortgage market. It does this by securitizing mortgage loans into mortgage-backed securities (MBS), which allows lenders to reinvest their assets into additional lending. This process effectively increases the number of mortgage lenders by reducing reliance on local savings and loan associations. Its sister organization is the Federal Home Loan Mortgage Corporation (FHLMC), better known as Freddie Mac.', '["clm_wiki_fannie-mae_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
