VALUES
  ('cs_mars_leadership', 'org_mars', 'overview', 'Leadership',
   'Formation Scientists have theorized that during the Solar System''s formation , Mars was created as the result of a random process of run-away accretion of material from the protoplanetary disk that orbited the Sun. Mars has many distinctive chemical features caused by its position in the Solar System. Elements with comparatively low boiling points, such as chlorine , phosphorus , and sulfur , are much more common on Mars than on Earth; these elements were probably pushed outward by the young Sun''s energetic solar wind . [1] ^ Cite error: The named reference ssr96_1_4_197 was invoked but never defined (see the help page ).', '["clm_wiki_mars_leadership"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   30, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
