VALUES
  ('cs_wynn-resorts_overview', 'org_wynn-resorts', 'overview', 'Overview',
   'Wynn Resorts, Limited is an American publicly traded corporation based in Paradise, Nevada, that is a developer and operator of high-end hotels and casinos. It was founded in 2002 by former Mirage Resorts Chairman and CEO Steve Wynn and is now run by CEO Craig Billings. As of 2020, the company has developed six properties.', '["clm_wiki_wynn-resorts_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
