VALUES
  ('cs_carmax_overview', 'org_carmax', 'overview', 'Overview',
   'CarMax, Inc. is a used vehicle retailer based in the United States. It operates two business segments: CarMax Sales Operations and CarMax Auto Finance. The company began as a side business of Circuit City Corporation, Inc., opening its first location in September 1993 in Richmond, Virginia. In 2021 CarMax, Inc. purchased remaining shares of Edmunds.com, Inc. (edmunds) making it a wholly owned subsidiary. As of January 2025, CarMax operates 253 locations.', '["clm_wiki_carmax_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
