INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_dte-energy_history', 'org_dte-energy', 'overview', 'History',
   'American energy company based DTE Energy Company DTE Energy Headquarters in Detroit, Michigan Type Public Traded as NYSE : DTE S&amp;P 500 component Industry Electric &amp; Gas Utilities Headquarters DTE Energy Headquarters , Detroit, Michigan , U.S. Key people Jerry Norcia (Executive chair) Joi Harris (President &amp; CEO) [1] Revenue US$ 12.5 billion (2024) Operating income US$2.09 billion (2024) Net income US$1.40 billion (2024) Total assets US$48.8 billion (2024) Total equity US$11.7 billion (2024) Number of employees 9,500 (2024) Subsidiaries DTE Electric Company DTE Gas DTE Vantage DTE Energy Trading Website dteenergy Footnotes [2] DTE Energy (formerly Detroit Edison until 1996) is an American diversified energy company involved in the development and management of energy-related businesses and services in the United States and Canada. Its operating units include an electric utility serving 2.2 million customers and a natural gas utility serving 1.3 million customers in Michigan . DTE is a national and international corporation. The DTE Energy portfolio includes non-utility energy businesses focused on power and industrial projects, energy marketing and trading. As of 2022, 54.16% of DTE''s electricity was generated from coal, 18.16% from nuclear, 14.22% from natural gas and 13.11% from renewable energy including wind, solar and hydroelectric. ^ body:not( ):not( ) "DTE Energy Executive Committee" . DTE. June 2019 . Retrieved June 24, 2019 . ^ "2024 Annual Report (Form 10-K)" . U.S. Securities and Exchange Commission. February 13, 2025.', '["clm_wiki_dte-energy_history"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   20, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_dte-energy_leadership', 'org_dte-energy', 'overview', 'Leadership',
   'Early 1900s DTE''s earliest direct corporate ancestor, the Edison Illuminating Company of Detroit, was founded in 1886. By the turn of the century, it split responsibility for commercial electric power in the fast-growing city of Detroit with the Peninsular Electric Light Company; the latter company controlled the city''s electric distribution network. In 1903, the two companies merged as the Detroit Edison Company, which began trading on January 17. That same year, construction began on the Delray 1 Power Plant, and Henry Ford , who had left Edison Illuminating four years earlier, founded Ford Motor Company . DTE''s gas operations trace their roots to 1849, when the City of Detroit Gas Company began operation with Philadelphia engineer Lemuel Davis as its first president. The company installed Detroit''s first gas lamps two years later, by which time it had changed its name to Detroit Gas Light Company. In 1903, the Detroit Gas Co. was renamed the Detroit City Gas Co. It secured franchises for Highland Park and Hamtramck and increased its customer base to more than 67,000. In 1904, Detroit Edison signed its first power contract with an automobile company — the Cadillac Motor Car Co. In 1905, a majority of the Detroit City Gas Co. was acquired by the American Light &amp; Traction Co., a holding company that controlled utility and transportation interests stretching from Grand Rapids to Milwaukee. With the added demand for electricity, the Delray 2 Power Plant was added in 1908. In 1913, Detroit City Gas acquired additional service territory that included the communities of River Rouge , Wyandotte , Dearborn , Ecorse and Trenton .', '["clm_wiki_dte-energy_leadership"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   30, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_dte-energy_operations', 'org_dte-energy', 'overview', 'Operations',
   '1920s Between 1924 and 1929, Detroit Edison increased its production capacity by building the Marysville , Trenton Channel and Delray 3 power plants.', '["clm_wiki_dte-energy_operations"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   40, 1, 1, unixepoch());
