VALUES
  ('cs_mosaic_history', 'org_mosaic', 'overview', 'History',
   'Mosaic materials Tepidarium of Dar Zmela house, Sousse Archaeological Museum Traditional mosaics are made of small cubes of roughly square pieces of stone or hand made glass enamel of different colours, known as tesserae . Some of the earliest mosaics were made of natural pebbles, originally used to reinforce floors. [1] Mosaic skinning (covering objects with mosaic glass) is done with thin enameled glass and opaque stained glass. Modern mosaic art is made from any material in any size ranging from carved stone, bottle caps, and found objects. Skull covered with turquoise , Museo Nacional de Antropología (México) ^ Dunbabin 1999 , p. 5.', '["clm_wiki_mosaic_history"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   20, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
