VALUES
  ('cs_cleveland-cliffs_overview', 'org_cleveland-cliffs', 'overview', 'Overview',
   'Cleveland-Cliffs Inc. is an American steel manufacturer based in Cleveland, Ohio. It specializes in the mining, beneficiation, and pelletizing of iron ore, as well as steelmaking, including stamping and tooling. The company is ranked 23rd on the list of steel producers and is the second-largest steel producer in the United States after Nucor. It is the largest flat-rolled steel producer in North America. The company is ranked 221st on the Fortune 500 and 1511th on the Forbes Global 2000.', '["clm_wiki_cleveland-cliffs_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
