-- 286. Corning Inc (slug=corning, wiki='Corning Inc')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_corning_overview', 'org_corning', 'overview', 'Overview',
   'Corning Incorporated is an American multinational technology company specializing in glass, ceramics, and related materials and technologies including advanced optics, primarily for industrial and scientific applications. Founded in 1851, the company was called Corning Glass Works for most of its history. Corning was known during the 20th century for its consumer product lines, such as including CorningWare and Visions Pyroceram-based cookware, Corelle Vitrelle tableware, and Pyrex glass bakeware. It divested its consumer product lines in 1998 by selling the Corning Consumer Products Company to Borden.', '["clm_wiki_corning_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
-- 287. Owens Corning (slug=owens-corning, wiki='Owens Corning')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_owens-corning_overview', 'org_owens-corning', 'overview', 'Overview',
   'Owens Corning is an American company that develops and produces insulation, roofing, and fiberglass composites and related products. It is the world''s largest manufacturer of fiberglass composites. It was formed in 1935 as a partnership between two major American glassworks, Corning Glass Works and Owens-Illinois. The company employs approximately 19,000 people around the world. Owens Corning has been a Fortune 500 company every year since the list was created in 1955. The Pink Panther is the company''s mascot and appears in most of their advertisements.', '["clm_wiki_owens-corning_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
