-- 347. Restaurant Brands International (slug=restaurant-brands, wiki='Restaurant Brands International')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_restaurant-brands_overview', 'org_restaurant-brands', 'overview', 'Overview',
   'Restaurant Brands International Inc. (RBI) is a Canadian multinational fast food holding company. It was formed in 2014 by the $12.5 billion merger between American fast food restaurant chain Burger King and Canadian coffee shop and fast food restaurant chain Tim Hortons, and expanded by the purchases of Popeyes and Firehouse Subs in 2017 and 2021, respectively. The company is the fifth-largest operator of fast food restaurants in the world after Subway, McDonald''s, Starbucks and Yum! Brands. They are based alongside Tim Hortons in Toronto. Burger King, Popeyes, and Firehouse Subs retain their existing operations and headquarters in Florida, with Burger King and Popeyes in Miami, and Firehouse in Jacksonville. The 2014 merger focused primarily on expanding the international reach of the Tim Hortons brand and providing financial efficiencies for both companies.', '["clm_wiki_restaurant-brands_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
