-- 380. Mohawk Industries (slug=mohawk, wiki='Mohawk Industries')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_mohawk_overview', 'org_mohawk', 'overview', 'Overview',
   'Mohawk Industries is an American flooring manufacturer based in Calhoun, Georgia. Mohawk produces floor covering products for residential and commercial applications in North America and residential applications in Europe. The company manufacturing portfolio consists of soft flooring products, hard flooring products, laminate flooring, sheet vinyl and luxury vinyl tile, natural stone and quartz countertops. In Europe, the company also produces and sells insulation, panels and mezzanine flooring. The company employs 43,000 people in operations in Australia, Brazil, Canada, Europe, Malaysia, Mexico, New Zealand, Russia and the United States. A Fortune 500 company, Mohawk is the world''s largest flooring manufacturer.', '["clm_wiki_mohawk_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
