VALUES
  ('cs_valspar_overview', 'org_valspar', 'overview', 'Overview',
   'The Valspar Corporation is an American manufacturer of paint and coatings based in Minneapolis, Minnesota. With over 11,000 employees in 26 countries and a company history that spans two centuries, it was the sixth largest paint and coating corporation in the world. Valspar was founded in 1806 as a paint dealership in Boston, Massachusetts. The Valspar name emerged in 1903 as the name of a clear varnish and became the company name in 1932.', '["clm_wiki_valspar_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
