VALUES
  ('cs_american-international_overview', 'org_american-international', 'overview', 'Overview',
   'American International Group, Inc. (AIG) is an American multinational finance and insurance corporation with operations in more than 200 countries and jurisdictions. As of 2023, AIG employed 25,200 people. The company primarily provides commercial and personal insurance products, including property and casualty insurance, liability coverage, accident and health insurance, and specialty insurance products. The company also provides risk management, multinational, and related insurance services to businesses and individuals. AIG is the title sponsor of the AIG Women''s Open golf tournament. In 2023, for the sixth consecutive year, DiversityInc named AIG among the Top 50 Companies for Diversity list.', '["clm_wiki_american-international_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
