INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_warnermedia_history', 'org_warnermedia', 'overview', 'History',
   'American media conglomerate (1972–2022) Warner Media, LLC. Final logo created by Wolff Olins and used from 2019 to 2022 30 Hudson Yards , WarnerMedia''s final headquarters, pictured in 2023 Trade name WarnerMedia [1] Formerly Warner Communications Inc. (1972–1990) Time Warner Inc. (1990–2001; 2003–2018) Time Warner Entertainment Company, L.P. (1992–2001) AOL Time Warner Inc. (2001–2003) Type Subsidiary Traded as NYSE : WCI (1972–1990) NYSE : TWX (1990–2001; 2003–2018) [2] [3] NYSE : AOL (2001–2003) Industry Mass media Entertainment Predecessors Kinney National Company (1961–1972) Time Inc. (1922–2018) America Online Turner Broadcasting System Founded February 10, 1972 &#59;&#32;54 years ago ( 1972-02-10 ) (as Warner Communications) January 10, 1990 &#59;&#32;36 years ago ( 1990-01-10 ) (as Time Warner) June 30, 1992 &#59;&#32;34 years ago ( 1992-06-30 ) (merged entertainment operations to form Time Warner Entertainment Company L.P.) January 11, 2001 &#59;&#32;25 years ago ( 2001-01-11 ) (Merged to form AOL Time Warner) June 15, 2018 &#59;&#32;8 years ago ( 2018-06-15 ) (as WarnerMedia) Founder Steve Ross (WCI) Richard Munro (Time) Defunct April 8, 2022 ;&#32;4 years ago ( 2022-04-08 ) Fate Spun off from AT&amp;T and merged with Discovery, Inc. Successor Warner Bros. Discovery Headquarters 30 Hudson Yards , New York City , United States [4] Area served Worldwide Revenue US$35.63 billion (2021) Operating income US$1.9 billion (2021) Number of employees 30,000 (2021) Parent AT&amp;T (2018–2022) Divisions WarnerMedia Studios &amp; Networks WarnerMedia News &amp; Sports WarnerMedia Sales &amp; Distribution WarnerMedia Direct WarnerMedia International Website warnermedia timewarner aoltimewarner (archived websites) Warner Media, LLC. , founded as Time Warner Inc. , &#91; a &#93; was an American multinational entertainment and media conglomerate headquartered at 30 Hudson Yards in Manhattan , New York City. After being acquired by AT&amp;T in June 2018, WarnerMedia was reorganized as a privately-owned subsidiary . The corporate predecessors to WarnerMedia are Time Inc . and Warner Communications Inc. ( WCI ). By the late 1960s, both companies began repositioning themselves as major players in cable television and mass media through multiple acquisitions, and they later underwent a stock-swap merger in March 1989, which was fully finalized on January 10, 1990. The newly established company, Time Warner, was the world’s largest media conglomerate for nearly 18 years', '["clm_wiki_warnermedia_history"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   20, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_warnermedia_leadership', 'org_warnermedia', 'overview', 'Leadership',
   'Kinney National and Warner Communications (1969–1990) Main articles: Kinney National Company and Time Inc. The "Big W" logo was designed by Saul Bass and is currently used by Warner Music Group WCI''s history stems back to Kinney National Services , which purchased the Warner Bros.-Seven Arts film studio in 1969, and later reincorporated as Warner Communications Inc. (WCI) in 1972 after divesting non-core businesses . Kinney National (renamed to Kinney Services) originally began as a service-based conglomerate , but after purchasing several entertainment businesses during the late 1960s, Kinney soon pivoted away from the service industry. By mid-1971, Kinney separated its non-media businesses into National Kinney Corporation At its reincorporation , Warner Communications served as the parent company for Warner Bros, National Periodical Publications (predecessor to DC Comics ), Warner Cable (later Time Warner Cable ), and Kinney Record Group International (renamed Warner-Elektra-Atlantic ). Warner''s longest-serving executive was Steven Ross . By 1984, Steven Ross was the sole Chairman, Chief Executive, and President of Warner Communications. The company made investments into the Sports Industry through Global Soccer Inc. and formed a joint venture with American Express known as Warner-Amex Satellite Entertainment. Warner-Amex would launch several cable channels, including MTV , Nickelodeon , and VH1 . In May 1986, this venture was sold to the original Viacom . A noteworthy acquisition done by Warner Communications was its purchase of Atari Inc. in 1976. For several years, Warner enjoyed success with the gaming company until the sudden Video Game Crash of 1983 . Suffering extensive losses, Warner divested parts of Atari along with several other companies it owned, and by the mid-1980s, WCI had rebounded in its financial performance. Warner Communications'' headquarters were at 75 Rockefeller Plaza in New York City . It had 26,300 employees in 1985, and operating income ', '["clm_wiki_warnermedia_leadership"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   30, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
