-- 628. Zoetis (slug=zoetis, wiki='Zoetis')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_zoetis_overview', 'org_zoetis', 'overview', 'Overview',
   'Zoetis Inc. (/zō-EH-tis/) is an American drug company, the world''s largest producer of medicine and vaccinations for pets and livestock. The company was a subsidiary of Pfizer, the world''s largest drug maker, but with Pfizer''s spinoff of its 83% interest in the firm it is now a completely independent company. The company directly markets its products in approximately 45 countries, and sells them in more than 100 countries. Operations outside the United States accounted for 50% of the total revenue. Contemporaneous with the spinoff in June 2013 S&P Dow Jones Indices announced that Zoetis would replace First Horizon National Corporation in the S&P 500 stock market index.', '["clm_wiki_zoetis_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
