VALUES
  ('cs_nexstar-media_overview', 'org_nexstar-media', 'overview', 'Overview',
   'Nexstar Media Group, Inc., is an American multimedia conglomerate headquartered in Irving, Texas, with operational headquarters in Midtown Manhattan and an additional office in Chicago. Founded on June 17, 1996, Nexstar is the largest television broadcasting company in the United States, owning 265 television stations—most of which are affiliated with the four major American television networks and MyNetworkTV—in markets as large as New York City and as small as San Angelo, Texas, and operating additional stations through local marketing agreements with certain affiliates such as Mission Broadcasting and Vaughan Media to satisfy existing regulations set in place by the Federal Communications Commission.', '["clm_wiki_nexstar-media_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
