-- 644. Camping World (slug=camping-world, wiki='Camping World')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_camping-world_overview', 'org_camping-world', 'overview', 'Overview',
   'Camping World Holdings, Inc. is an American corporation specializing in selling recreational vehicles (RVs), recreational vehicle parts, and recreational vehicle service. They also sell supplies for camping. The company has its headquarters in Lincolnshire, Illinois. In October 2016 it became a publicly traded company when it raised $251 million in an IPO. Camping World has 202 locations. In addition to its RV dealerships and accessories stores, the company sells goods through phone order and online. It claims to be the world''s largest supplier of RV parts and supplies.', '["clm_wiki_camping-world_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
