-- 646. Vivint Solar (slug=vivint-solar, wiki='Vivint Solar')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_vivint-solar_overview', 'org_vivint-solar', 'overview', 'Overview',
   'Vivint Solar was an American provider of photovoltaic solar energy generation systems, primarily for residential customers. The company was established in 2011 as an offshoot of home automation and security company Vivint and was headquartered in Lehi, Utah. The company primarily used a power purchase agreement (PPA) business model where Vivint Solar installed and maintained a solar system on a customer''s home, then sold power to the customer at an agreed upon rate for a set term. In 2020, the company was purchased by Sunrun, another solar company primarily focused on the PPA business model for $3.2 billion.', '["clm_wiki_vivint-solar_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
