-- 720. Krispy Kreme (slug=krispy-kreme, wiki='Krispy Kreme')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_krispy-kreme_overview', 'org_krispy-kreme', 'overview', 'Overview',
   'Krispy Kreme, Inc. is an American multinational doughnut company and coffeehouse chain. Krispy Kreme was founded by Vernon Rudolph (1915–1973), who bought a yeast-raised recipe from a New Orleans chef, rented a building in 1937 in what is now historic Old Salem in Winston-Salem, North Carolina, and began selling to local grocery stores. Steady growth preceded an ambitious expansion as a public company in the period 2000 to 2016, which ultimately proved unprofitable. In 2016, the company returned to private ownership under JAB Holding Company, a private Luxembourg-based firm. In July 2021, Krispy Kreme became publicly traded again on the Nasdaq. The brand name is a deliberate non-standard spelling of "crispy cream", for marketing effect.', '["clm_wiki_krispy-kreme_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
