VALUES
  ('cs_costco_overview', 'org_costco', 'overview', 'Overview',
   'Costco Wholesale Corporation is an American multinational corporation that operates a chain of membership-only big-box warehouse club retail stores. As of 2025, Costco is the third-largest retailer in the world, and as of August 2024, the world''s largest retailer of beef, poultry, organic produce, and wine, with just under a third of American consumers regularly shopping at Costco warehouses. As of 2026, Costco is ranked 12th on the Fortune 500 rankings of the largest United States corporations by total revenue, and is also ranked as the largest grocery retailer in Canada.', '["clm_wiki_costco_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
