VALUES
  ('cs_davita_overview', 'org_davita', 'overview', 'Overview',
   'DaVita Inc., incorporated in Delaware and headquartered in Denver, provides kidney dialysis services through a network of 2,657 outpatient centers in the United States, serving 200,500 patients, and 585 outpatient centers in 14 other countries serving 94,500 patients. The company primarily treats end-stage renal disease (ESRD), which requires patients to undergo kidney dialysis, often 3 times per week for the rest of their lives unless they receive a kidney transplant via organ donation.', '["clm_wiki_davita_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
