VALUES
  ('cs_nisource_overview', 'org_nisource', 'overview', 'Overview',
   'NiSource Inc. is one of the largest fully regulated utility companies in the United States, serving approximately 3.5 million natural gas customers and 500,000 electric customers across six states through its local Columbia Gas and NIPSCO brands. The company, based in Merrillville, Indiana, has more than 8,000 employees. As of 2018, NiSource is the sole Indiana-based utility company.', '["clm_wiki_nisource_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
