-- 834. ResMed (slug=resmed, wiki='ResMed')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_resmed_overview', 'org_resmed', 'overview', 'Overview',
   'ResMed Inc. is a medical equipment company based in San Diego, California, and founded in Australia. It primarily provides cloud-connectable medical devices for the treatment of sleep apnea, chronic obstructive pulmonary disease (COPD), and other respiratory conditions. Resmed produced hundreds of thousands of ventilators and bilevel devices to help treat the respiratory symptoms of patients with COVID-19. Resmed also provides software to out-of-hospital care agencies to streamline transitions of care into and between these care settings for seniors and their care providers.', '["clm_wiki_resmed_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
