VALUES
  ('cs_ameris_overview', 'org_ameris', 'overview', 'Overview',
   'Ameris Bancorp is an American bank holding company headquartered in Atlanta, Georgia. Through its bank subsidiary, Ameris Bank, the company operates full-service branches in Georgia, Alabama, Florida, North Carolina and South Carolina, and mortgage-only locations in Georgia, Alabama, Florida, North Carolina, South Carolina, Virginia, Maryland, and Tennessee. The company offers online and mobile banking options for both consumers and businesses.', '["clm_wiki_ameris_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
