VALUES
  ('cs_walgreens_overview', 'org_walgreens', 'overview', 'Overview',
   'Walgreens is an American pharmacy store chain headquartered in Deerfield, Illinois. It is the second largest pharmacy chain in the United States, behind CVS Pharmacy. Walgreens operates 8,000 stores serving 9 million customers daily in the United States with 211,000 team members of 2026. In addition to pharmacy services, Walgreens also offers photo services.', '["clm_wiki_walgreens_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
