VALUES
  ('cs_gap_overview', 'org_gap', 'overview', 'Overview',
   'The Gap, Inc., commonly known as Gap Inc., headquartered in San Francisco, California, is an American multinational clothing and accessories retailer. The company operates four primary divisions: the namesake Gap, Banana Republic, Old Navy, and Athleta. Gap Inc. is one of the largest apparel retailers in the United States. It operates 3,569 stores. Zac Posen is the creative director of the Gap.', '["clm_wiki_gap_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
