VALUES
  ('cs_kansas-city-southern_overview', 'org_kansas-city-southern', 'overview', 'Overview',
   'Kansas City Southern (KCS) was a transportation holding company with railroad investments in the United States, Mexico, and Panama and operated from 1887 to 2023. The KCS rail network included about 7,299 miles (11,747 km) of track in the U.S. and Mexico.', '["clm_wiki_kansas-city-southern_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
