-- 977. MongoDB Inc. (slug=mongodb, wiki='MongoDB Inc.')
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_mongodb_overview', 'org_mongodb', 'overview', 'Overview',
   'MongoDB, Inc. is an American software company that develops and provides commercial support for the source-available database engine MongoDB, a database for unstructured data. Over the years, the company has expanded the product from its NoSQL roots to have broader appeal to enterprise customers, such as adding ACID and transactions.', '["clm_wiki_mongodb_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
