VALUES
  ('cs_hess_overview', 'org_hess', 'overview', 'Overview',
   'Hess Corporation is an American global independent energy company involved in the exploration and production of crude oil and natural gas. It was formed by the merger of Hess Oil and Chemical and Amerada Petroleum in 1968. Leon Hess was CEO from the early 1960s until 1995, after which his son John B Hess succeeded him as chairman and CEO. The company agreed to be acquired by rival oil company Chevron in October 2023, and the acquisition closed in July 2025.', '["clm_wiki_hess_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'orgs_sections_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
